entries[439712] = { ["name"] = "Bismuth Seam", ["text"] = "5 yd range\n2.5 sec cast\nA very common metal found across Khaz Algar. Despite being mundane, it is often desired in high quantities by skilled craftsman due to its versatile properties.\n\nEven beneath the surface, seams rich in usable metal are a rare and exciting sight. They can typically be found on walls or ceilings in especially narrow spaces." }
entries[439713] = { ["name"] = "Aqirite Seam", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar. While it can sometimes be found on the surface, it's prevalence increases as one nears Azj-Kahet. Although it has varied uses, engineers in particular often take a keen interest in acquiring large quantities of it.\n\nEven beneath the surface, seams rich in usable metal are a rare and exciting sight. They can typically be found on walls or ceilings in especially narrow spaces." }
entries[439714] = { ["name"] = "Ironclaw Seam", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar, predominantly near or on the surface. As it is known for being extremely durable, blacksmiths often take a keen interest in acquiring large quantities of it.\n\nEven beneath the surface, seams rich in usable metal are a rare and exciting sight. They can typically be found on walls or ceilings in especially narrow spaces." }
entries[439715] = { ["name"] = "Crystallized Bismuth", ["text"] = "5 yd range\n2.5 sec cast\nA very common metal found across Khaz Algar. Despite being mundane, it is often desired in high quantities by skilled craftsman due to its versatile properties.\n\nDue to their proximity to the Coreway, some deposits have a direct connection with the World Soul. Miners who gather from them will receive a small blessing in addition to some Crystalline Powder; a useful reagent in many crafts." }
entries[439716] = { ["name"] = "Crystallized Aqirite", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar. While it can sometimes be found on the surface, it's prevalence increases as one nears Azj-Kahet. Although it has varied uses, engineers in particular often take a keen interest in acquiring large quantities of it.\n\nDue to their proximity to the Coreway, some deposits have a direct connection with the World Soul. Miners who gather from them will receive a small blessing in addition to some Crystalline Powder; a useful reagent in many crafts." }
entries[439717] = { ["name"] = "Crystallized Ironclaw", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar, predominantly near or on the surface. As it is known for being extremely durable, blacksmiths often take a keen interest in acquiring large quantities of it.\n\nDue to their proximity to the Coreway, some deposits have a direct connection with the World Soul. Miners who gather from them will receive a small blessing in addition to some Crystalline Powder; a useful reagent in many crafts." }
entries[439718] = { ["name"] = "Weeping Bismuth", ["text"] = "5 yd range\n2.5 sec cast\nA very common metal found across Khaz Algar. Despite being mundane, it is often desired in high quantities by skilled craftsman due to its versatile properties.\n\nThe Black Blood of the Old Gods has begun to pool beneath Khaz Algar, and its festering presence has even had an effect on the precious metals it touches. Miners who brave the darkest depths to gather from these deposits will experience agony the likes of which mortals were not meant to endure. Fortunately, survivors will recover some Writhing Samples for their efforts." }
entries[439719] = { ["name"] = "Weeping Aqirite", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar. While it can sometimes be found on the surface, it's prevalence increases as one nears Azj-Kahet. Although it has varied uses, engineers in particular often take a keen interest in acquiring large quantities of it.\n\nThe Black Blood of the Old Gods has begun to pool beneath Khaz Algar, and its festering presence has even had an effect on the precious metals it touches. Miners who brave the darkest depths to gather from these deposits will experience agony the likes of which mortals were not meant to endure. Fortunately, survivors will recover some Writhing Samples for their efforts." }
entries[439720] = { ["name"] = "Weeping Ironclaw", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar, predominantly near or on the surface. As it is known for being extremely durable, blacksmiths often take a keen interest in acquiring large quantities of it.\n\nThe Black Blood of the Old Gods has begun to pool beneath Khaz Algar, and its festering presence has even had an effect on the precious metals it touches. Miners who brave the darkest depths to gather from these deposits will experience agony the likes of which mortals were not meant to endure. Fortunately, survivors will recover some Writhing Samples for their efforts." }
entries[439721] = { ["name"] = "EZ-Mine Bismuth", ["text"] = "5 yd range\n2.5 sec cast\nA very common metal found across Khaz Algar. Despite being mundane, it is often desired in high quantities by skilled craftsman due to its versatile properties.\n\nNature works in mysterious ways, but there is nothing natural about rocks covered in dynamite! Abnormally rich metal deposits spotted by \"helpful\" Engineers are sometimes rigged up for detonation for an easy yield, but they are often abandoned when the demolitionist come to their senses.\n\nKeeping one's distance and mining delicately may be enough to chip off a piece or two, but the process of natural selection need not be explained further.\n\nGood luck!" }
entries[439722] = { ["name"] = "EZ-Mine Aqirite", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar. While it can sometimes be found on the surface, it's prevalence increases as one nears Azj-Kahet. Although it has varied uses, engineers in particular often take a keen interest in acquiring large quantities of it.\n\nNature works in mysterious ways, but there is nothing natural about rocks covered in dynamite! Abnormally rich metal deposits spotted by \"helpful\" Engineers are sometimes rigged up for detonation for an easy yield, but they are often abandoned when the demolitionist come to their senses.\n\nKeeping one's distance and mining delicately may be enough to chip off a piece or two, but the process of natural selection need not be explained further.\n\nGood luck!" }
entries[439723] = { ["name"] = "EZ-Mine Ironclaw", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar, predominantly near or on the surface. As it is known for being extremely durable, blacksmiths often take a keen interest in acquiring large quantities of it.\n\nNature works in mysterious ways, but there is nothing natural about rocks covered in dynamite! Abnormally rich metal deposits spotted by \"helpful\" Engineers are sometimes rigged up for detonation for an easy yield, but they are often abandoned when the demolitionist come to their senses.\n\nKeeping one's distance and mining delicately may be enough to chip off a piece or two, but the process of natural selection need not be explained further.\n\nGood luck!" }
entries[439724] = { ["name"] = "Camouflaged Bismuth", ["text"] = "5 yd range\n2.5 sec cast\nA very common metal found across Khaz Algar. Despite being mundane, it is often desired in high quantities by skilled craftsman due to its versatile properties.\n\nAlthough it is already peculiar that some of the local plantlife on Khaz Algar have adapted to hide in plain sight, some rocks have mastered this skill, too. Observant craftsman, namely alchemists and engineers, have developed methods to pierce through this mysterious veil for those willing to invest in their success.\n\nAs for everyone else, their pockets will be a little less heavy than yours." }
entries[439725] = { ["name"] = "Camouflaged Aqirite", ["text"] = "5 yd range\n2.5 sec cast\nA rare metal found throughout Khaz Algar. While it can sometimes be found on the surface, it's prevalence increases as one nears Azj-Kahet. Although it has varied uses, engineers in particular often take a keen interest in acquiring large quantities of it.\n\nAlthough it is already peculiar that some of the local plantlife on Khaz Algar have adapted to hide in plain sight, some rocks have mastered this skill, too. Observant craftsman, namely alchemists and engineers, have developed methods to pierce through this mysterious veil for those willing to invest in their success.\n\nAs for everyone else, their pockets will be a little less heavy than yours." }
